architecture rtl of DPD_CORE_opb_if is


  -- OPB constants
  constant baseaddr_c     : std_logic_vector(0 to 31) := std_logic_vector(to_unsigned(baseaddr_g,28) & "0000");
  constant opb_awidth_c   : natural := 32;
  constant opb_dwidth_c   : natural := 32;
  constant slv_dwidth_c   : natural := 32;
  constant slv_awidth_c   : natural := 15;

  -- OPB FSM signals and constants
  type fsm_state_t is (idle, selected, wait_state0_for_memory, wait_state1_for_memory, xfer, hold_no_adr);
  signal fsm_state       : fsm_state_t;

  -- internal OPB signals
  signal chip_select        : std_logic;
  signal opb_fwxfer_in      : std_logic;
  signal opb_hwxfer_in      : std_logic;
  signal opb_rnw_in         : std_logic;
  signal opb_abus_in        : std_logic_vector(0 to opb_awidth_c-1);
  signal opb_dbus_in        : std_logic_vector(0 to opb_dwidth_c-1);
  signal sl_no_read_adr     : std_logic;
  signal sl_no_write_adr    : std_logic;

  -- internal slave response signals
  -- real slave response signals is gated with opb_select
  signal fw_ack             : std_logic;
  signal xfer_ack           : std_logic;
  signal dbus_en            : std_logic;
  signal err_ack            : std_logic;
  signal retry              : std_logic;

  -- internal gated xfer_ack signal
  signal xfer_ack_int       : std_logic;

begin

  -----------------------------------------------------------------------------
  -- signal assignments
  -----------------------------------------------------------------------------
  sl_toutsup  <= '0';
  sl_hwack    <= '0';

  sl_xferack  <= xfer_ack_int;

  -- gated slave response signals
  sl_fwack    <= fw_ack   and opb_select;
  xfer_ack_int     <= xfer_ack and opb_select;
  sl_dbusen   <= dbus_en  and opb_select;
  sl_errack   <= err_ack  and opb_select;
  sl_retry    <= retry    and opb_select;


  -----------------------------------------------------------------------------
  -- Read Write to the DPD_CORE registers
  -----------------------------------------------------------------------------
  read_write_dpd_core_registers: process (clk_opb, rst_opb)
  begin
    if rst_opb = '1' then
      xfer_ack               <= '0';
      dbus_en                <= '0';
      err_ack                <= '0';
      retry                  <= '0';

      sl_no_write_adr     <= '0';
      sl_dbus             <= (others => '0');
      sl_no_read_adr      <= '0';
      dpd_core_ram_addr    <= (others => '0');
      dpd_core_ram_sel     <= '0';
      dpd_core_ram_wr      <= '0';
      dpd_core_ram_wr_data <= (others => '0');
      dpd_core_ram_rd      <= '0';
    elsif clk_opb'event and clk_opb = '1' then
      -- Default values
      xfer_ack               <= '0';
      dbus_en                <= '0';
      err_ack                <= '0';
      retry                  <= '0';

      sl_no_write_adr     <= '0';
      sl_dbus             <= (others => '0');
      sl_no_read_adr      <= '0';

      dpd_core_ram_addr     <= opb_abus_in(19 to 29);
      dpd_core_ram_sel      <= '0';
      dpd_core_ram_wr       <= '0';
      dpd_core_ram_rd       <= '0';
      dpd_core_ram_wr_data  <= opb_dbus_in(0 to 31);

      -- write registers
      if (fsm_state = selected or fsm_state = xfer) and opb_rnw_in = '0' then
        if (fsm_state = selected and chip_select = '1') then
          -- Default transfer ack could be canceled by write to ROM,
          -- write to memory or write outside memory map.
          xfer_ack <= '1';
        end if;
        case opb_abus_in(opb_awidth_c-3-(slv_awidth_c-3) to opb_awidth_c-3) is

          when others =>
            -- OUTSIDE OF MEMORY MAP or EXTERNAL MEMORY
            xfer_ack        <= '0';
            sl_no_write_adr <= '1';
        end case;
      end if;

      -- write mem
      if (fsm_state = selected or fsm_state = wait_state0_for_memory or fsm_state = wait_state1_for_memory or fsm_state = xfer)
          and opb_rnw_in = '0' then

        -- External memory DPD_CORE_RAM between HEX address 00010000 and 00011ffc
        if (unsigned(opb_abus_in(17 to 29)) >= "0000000000000") and  -- Start address
           (unsigned(opb_abus_in(17 to 29)) <= "0011111111111") then  -- Stop address
          sl_no_write_adr   <= '0';
          dpd_core_ram_sel                            <= '1';   -- Set select memory
          if (fsm_state = selected and chip_select = '1') then
            xfer_ack           <= '0';
          end if;
          if (fsm_state = wait_state1_for_memory and chip_select = '1') then
            if (dpd_core_ram_busy = '1') then  -- Check that memory is not busy
              retry            <= '1';
            else
              xfer_ack         <= '1';
              dbus_en          <= '1';
            end if;
          end if;
          if xfer_ack_int = '1' then
            dpd_core_ram_wr  <= '1';   -- Set WRITE Strob
          end if;
        end if;
      end if;

      -- read registers
      if (fsm_state = selected or fsm_state = xfer) and opb_rnw_in = '1' then
        if (fsm_state = selected and chip_select = '1') then
          -- Default transfer ack and data bus enable; could be canceled by
          -- read from W or PUT register, read from memory or read outside memory map.
          xfer_ack          <= '1';
          dbus_en           <= '1';
        end if;
        case opb_abus_in(opb_awidth_c-3-(slv_awidth_c-3) to opb_awidth_c-3) is

          when others =>
            -- OUTSIDE OF MEMORY MAP or EXTERNAL MEMORY
            xfer_ack       <= '0';
            sl_dbus        <= X"DEADDEAD";
            sl_no_read_adr <= '1';
        end case;

        if opb_fwxfer_in = '0' and opb_hwxfer_in = '1' then
          -- half word read access
          if opb_abus_in(30) = '0' then
            sl_dbus(16 to 31)  <= X"0000";
          else
            sl_dbus(0 to 15)   <= X"0000";
          end if;
        end if;
        if opb_fwxfer_in = '0' and opb_hwxfer_in = '0' then
          -- byte word read access
          case opb_abus_in(30 to 31) is
            when "00" =>
              sl_dbus(8 to 31)  <= X"000000";
            when "01" =>
              sl_dbus(0 to 7)   <= X"00";
              sl_dbus(16 to 31) <= X"0000";
            when "10" =>
              sl_dbus(0 to 15)  <= X"0000";
              sl_dbus(24 to 31) <= X"00";
            when "11" =>
              sl_dbus(0 to 23)  <= X"000000";
            when others =>
              sl_dbus           <= X"DEADDEAD";
          end case;
        end if;
      end if;

      -- read mem
      if (fsm_state = selected or fsm_state = wait_state0_for_memory or fsm_state = wait_state1_for_memory or fsm_state = xfer)
          and opb_rnw_in = '1' then

        -- External memory DPD_CORE_RAM between HEX address 00010000 and 00011ffc
        if (unsigned(opb_abus_in(17 to 29)) >= "0000000000000") and  -- Start address
           (unsigned(opb_abus_in(17 to 29)) <= "0011111111111") then  -- Stop address
          sl_no_read_adr    <= '0';
          sl_dbus           <= (others => '0');
          sl_dbus(0 to 31) <= dpd_core_ram_rd_data;
          dpd_core_ram_sel                            <= '1';   -- Set select memory
          if (fsm_state = selected and chip_select = '1') then
            xfer_ack           <= '0';
            dbus_en            <= '0';
            dpd_core_ram_rd  <= '1';   -- Set READ Strob
          end if;
          if (fsm_state = wait_state1_for_memory and chip_select = '1') then
            if (dpd_core_ram_busy = '1') then  -- Check that memory is not busy
              retry            <= '1';
            else
              xfer_ack         <= '1';
              dbus_en          <= '1';
            end if;
          end if;
        end if;
      end if;

    end if;
  end process read_write_dpd_core_registers;

  -----------------------------------------------------------------------------
  -- Interrupt trig logic
  --
  -- Interrupt can be level or edge triggered.
  -- This process creates the edge signal.
  -----------------------------------------------------------------------------
  irq_trig_process : process(clk_opb, rst_opb)
  begin
    if rst_opb = '1' then
    elsif clk_opb'event and clk_opb = '1' then
    end if;
  end process irq_trig_process;

  -----------------------------------------------------------------------------
  -- Interrupt logic
  --
  -- Interrupt will be generated if not all unmasked bits in
  -- the trap register is zero.
  -----------------------------------------------------------------------------
  irq_generation_process : process(clk_opb, rst_opb)
  begin
    if rst_opb = '1' then
    elsif clk_opb'event and clk_opb = '1' then
      -- Default value
    end if;
  end process irq_generation_process;

  -----------------------------------------------------------------------------
  -- Chip select decoding
  -----------------------------------------------------------------------------
  chip_select <= '1' when opb_select = '1' and opb_abus_in(0 to opb_awidth_c-1-slv_awidth_c) = baseaddr_c(0 to opb_awidth_c-1-slv_awidth_c) else '0';

  -----------------------------------------------------------------------------
  -- Synchronization of inputs
  -----------------------------------------------------------------------------
  sync_opb_inputs : process(clk_opb, rst_opb)
  begin
    if rst_opb = '1' then
      opb_fwxfer_in       <= '0';
      opb_hwxfer_in       <= '0';
      opb_rnw_in          <= '0';
      opb_dbus_in         <= (others => '0');
      opb_abus_in         <= (others => '0');
    elsif clk_opb'event and clk_opb = '1' then
      opb_fwxfer_in       <= opb_fwxfer;
      opb_hwxfer_in       <= opb_hwxfer;
      opb_rnw_in          <= opb_rnw;
      opb_dbus_in         <= opb_dbus(opb_dwidth_c-1-(slv_dwidth_c-1) to opb_dwidth_c-1);
      opb_abus_in         <= opb_abus;
    end if;
  end process sync_opb_inputs;

  -----------------------------------------------------------------------------
  -- FSM for OPB bus states
  -----------------------------------------------------------------------------
  fsm_opb : process(clk_opb, rst_opb)
  begin
    if rst_opb = '1' then
      fsm_state             <= idle;
      fw_ack                <= '0';
    elsif clk_opb'event and clk_opb = '1' then

     fw_ack                 <= '0';
 
     case fsm_state is

        when idle =>
          if (chip_select = '1') then
            fsm_state       <= selected;
          end if;

        when selected =>
          if (chip_select = '1') then
            if (false
                -- External memory DPD_CORE_RAM between HEX address 00010000 and 00011ffc
                or ((unsigned(opb_abus_in(17 to 29)) >= "0000000000000") and   -- Start address
                    (unsigned(opb_abus_in(17 to 29)) <= "0011111111111"))       -- Stop address
               ) then
              fsm_state   <= wait_state0_for_memory;
            else
              fw_ack        <= '1';
              fsm_state     <= xfer;
            end if;
          else
            fsm_state       <= idle;
          end if;

        when wait_state0_for_memory =>
          if (chip_select = '1') then
            fsm_state       <= wait_state1_for_memory;
          else
            fsm_state       <= idle;
          end if;

        when wait_state1_for_memory =>
          if (chip_select = '1') then
            fw_ack          <= '1';
            fsm_state       <= xfer;
          else
            fsm_state       <= idle;
          end if;

        when xfer =>
          if (chip_select = '1' and (sl_no_read_adr = '1' or sl_no_write_adr = '1')) then
            fsm_state       <= hold_no_adr;
          else
            fsm_state       <= idle;
          end if;

        when hold_no_adr =>
          if (chip_select = '0') then
            fsm_state       <= idle;
          end if;

        when others =>
          fsm_state         <= idle;

      end case;
    end if;
  end process fsm_opb;

end architecture rtl;
